local _, WFI = ...
WFI.Data.add("quest", {
  [97005] = { nil, "Porta la Chol'aruk's Head a Bainham, nelle Barrens.", "Si dice che un colossale abominio abbia la sua tana in una caverna a nord-ovest di qui, sull'altopiano noto come Thorn Hill. I Razormane lo chiamano Chol'aruk, \"il divoratore\", e chi l'ha visto dice che è così enorme da poter inghiottire un orco intero.\n\nIn pochi credono a simili storie, ma io sì... perché ne ho combattuto uno simile di persona. Sull'onore di coloro che ho perso per colpa di queste creature, questa bestia deve morire.\n\nRaduna alleati forti e trova la tana di Chol'aruk. Uccidi l'abominio e portami la sua testa.", nil, nil, nil, 0x5efacf98, 0xef594ded, nil, nil, "m..mm" },
  [97234] = { "La sala di lettura", "Porta il materiale di lettura impacchettato alla biblioteca di Stormwind.", "Sei qui per discutere i significati più profondi delle nostre celebri leggende? No?\n\nBe', quando hai finito di guardarti intorno, potresti portare questo in biblioteca per me? Stiamo scambiando alcune delle nostre opere meno apprezzate con letture più moderne. Ho una lista di tomi che sono certo il bibliotecario potrà procurarci secondo il nostro accordo attuale.\n\nRinfreschi del circolo offerti da noi, se ci dai una mano.", nil, nil, 0x3eee958f, 0xfdbaaa05, 0x221f294c, nil, nil, "...mm" },
  [97236] = { nil, "Consegna il Fang of Githyiss a qualcuno interessato allo studio dei ragni, ad Aldrassil.", "Un esemplare fresco di una bestia di queste dimensioni è una bella scoperta. Forse qualcuno ad Aldrassil che conosce lo studio dei ragni sarebbe interessato alla zanna.", nil, "Oh, oh. Quanto adoro le sorprese, {name}.\n\nQuesto esemplare aiuterà di sicuro i miei studi.", nil, 0xe6a4e5ad, 0x9adc9237, nil, 0xd5fbb580, "m..m." },
  [97237] = { "Scaffali svuotati", "Trova ciascuno dei materiali di lettura nascosti da qualche parte nella biblioteca, poi torna da Roy Lewells, nel Park di Stormwind.", "Ho controllato il nostro inventario e tutti i titoli elencati dal signor Lewells sono attualmente disponibili.\n\nDovrai però prenderli dagli scaffali da te. Parte del nostro dovere di bibliotecari è la vigilanza, e per questo riprenderò la mia supervisione dei registri.\n\nRiportare il materiale a Roy per conto suo non ti renderà responsabile della sua restituzione: come indica il suo biglietto, fai da corriere ufficiale del circolo di lettura. Sarà la loro istituzione a portarne il peso.\n\nBuona giornata, {name}.", nil, nil, 0xa2b3432f, 0xa187b795, 0x7efc8438, nil, nil, "...mm" },
  [97243] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [97244] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [97245] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [97253] = { "Pezzi e pezzetti", "Raccogli $N1 Handfuls of Complicated Parts dall'accampamento pirata superiore a sud di Ratchet, poi torna da Wrenix the Wretched, a Ratchet.", "Ehi, hai un secondo?\n\nA quanto pare nessuno di quelli che ho mandato a occuparsi del recente problema dei pirati è tornato vivo. Dopo cinque o sei tentativi ho pensato: \"e se mandassi una macchina?\" Si è scoperto che le scimitarre fanno da cacciavite all'occorrenza, e prima che potessi richiamarla a casa era già a pezzi, sparsa per tutto il loro accampamento!\n\nMi servono quei pezzi, e visto che è solo una piccola missione di recupero, scommetto che le tue probabilità di sopravvivere sono molto più alte di quelle degli altri. Che ne dici?", "Non una parola di più finché le tue tasche non tintinnano di metallo!", "Wooooah! Bel colpo, amico! Mi hai risparmiato un'altra delle insopportabili lezioni di Gagsprocket sul costo del metallo. E soprattutto, posso buttarmi subito a costruire il mio prossimo prototipo.\n\nEhm, non avevo previsto una ricompensa... Ti piacciono le scatole?", 0xc374d63c, 0xdd7fd206, 0xd685419d, 0xedc33a12, 0x0ab437e0, "....." },
  [97257] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [97263] = { "Il tuo pacco è arrivato", "Consegna il pacco smarrito di Eldrun.", "<Diversi pacchi smarriti sono stati lasciati vicino alla cassetta della posta. Noti che uno di essi è destinato da Aerie Peak a Ironforge, a Eldrun Stormbreaker. È contrassegnato come \"urgente\".>", "Cos'hai lì?", "Cosa! Vado ogni giorno alla cassetta della posta vicino alla banca a cercare questo pacco! Questa città deve sistemare la sua pianta. Non è facile orientarsi come ad Aerie Peak!\n\nVediamo cosa c'è... attrezzi per intagliare totem... un'ascia di scorta... una specie di aggeggio goblin? Questo non l'ho ordinato! Ah, lo rispedirò indietro.\n\nEhm... cioè... grazie per avermi portato tutto questo. Ecco qualcosa per il disturbo.", 0xb90615cc, 0x0f13a33f, 0xc3642e31, 0xdcbf39a7, 0xa4d81308, "....." },
  [97265] = { "Odio per gli Hatefury", "Sconfiggi diversi satiri Hatefury a Sargeron, a Desolace, poi torna da Aka'rai, allo Shadowprey Village.", "Hai mai fatto un patto con un satiro, amico?\n\nIo sì. Come potevo resistere? La promessa di potere, di conoscenze ben oltre quelle di qualsiasi tomo... e in più un servitore entusiasta e carismatico. Cosa potevo chiedere di più?\n\nBah, ovviamente non si sarebbero mai inginocchiati davanti a un mortale. Ho contrattato quando non avevo nulla, e sono stato scartato con ancora meno.\n\nOra voglio vendetta. Vendetta contro gli Hatefury. Assalta il loro accampamento a nord-est! Macchia la terra del loro sangue immondo.", nil, nil, 0x80d3ee17, 0x24ba3490, 0x9c7d33bf, nil, nil, "...mm" },
  [97284] = { "La vendetta di Vahlarriel", "Uccidi gli orchi della Burning Blade alla Thunder Axe Fortress, a Desolace, poi torna da Vahlarriel Demonslayer, a Nijel's Point.", "Se Malem è ancora viva, sospetto che gli orchi della Burning Blade si aspettino che qualcuno venga a cercarla molto presto. Saranno di certo pronti a combattere.\n\nPreferirei che tenessi un profilo basso e restassi alla larga, ma molto più probabilmente cercheranno di affrontarti, lama contro Burning Blade, a ogni occasione.\n\nQuindi che ne dici di tenere il conto fin dall'inizio? Uccidine quanti più puoi, e farò in modo che ne valga la pena.", nil, nil, 0x8067ec59, 0xf8a6125b, 0x9c85e944, nil, nil, "...mm" },
  [97894] = { "Affari ad Auberdine", "Va' a vedere come sta Gorbold Steelhand, ad Auberdine, a Darkshore.\n\nBorgus ha parlato di una nave al molo più a sud dello Stormwind Harbor che può portarti lì.", "Piacere di conoscerti! Mi chiamo Borgus, dell'unica e sola famiglia Steelhand. Puoi sempre contare su uno Steelhand per un affare onesto!\n\nQualche settimana fa mio fratello Gorbold si è unito a una bancarella di mercanti ad Auberdine. C'è un sacco di soldi da fare rifornendo le navi lì, te lo dico io! Fortunello.\n\nNon ho più sue notizie da allora: ti spiacerebbe controllare come sta, se vai da quelle parti?\n\nNel porto c'è una nave nuova che ti porterà dritto lì. Va' al molo più a sud: non puoi sbagliare!", nil, "Ti manda il vecchio Borgy? Si preoccupa sempre per me.\n\nUn altro paio di mani ci farebbe proprio comodo qui. Gli affari si sono quasi fermati dopo la recente tragedia, e penso che tu possa aiutare a rimettere le cose a posto.", 0x05e986b2, 0xc51e34fa, 0x4f88604b, nil, 0xe4fd9705, "...m." },
  [97899] = { "Campeggio 101: Alchemy", nil, "Quindi hai scelto di preparare intrugli e pozioni come alchimista. Sono sicuro che ti tornerà utile nei tuoi viaggi.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Mana Well per il tuo accampamento. Costruiscine uno e tutti i guaritori e gli incantatori accorreranno per un sorso rinfrescante.", nil, nil, 0x32f4ba12, nil, 0xf6c52c29, nil, nil, ".m.mm" },
  [97900] = { "Campeggio 101: Blacksmithing", nil, "Quindi sei <diventato/diventata> fabbro. Ottima scelta, se vuoi essere <sicuro/sicura> che le tue lame non perdano mai il filo.\n\nCredo di conoscere qualcuno che può aiutarti insegnandoti a creare una Sharpening Wheel. Portane una al tuo accampamento e tutti i guerrieri e i ladri della zona faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, nil, 0x469a706e, nil, nil, ".m.mm" },
  [97901] = { "Campeggio 101: Enchanting", nil, "Gli incantatori rendono tutto migliore e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. È così importante trovare un po' di svago durante il riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando tornerai sulla vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [97902] = { "Campeggio 101: Engineering", nil, "Gli ingegneri come te sanno inventare ogni sorta di aggeggi, robot e bombe, per divertimento e per profitto.\n\nConosco qualcuno che può insegnarti a creare un Reagent Bot per il tuo accampamento. Questo utile automa può tenerti ben rifornito, così che tu e i tuoi alleati non restiate mai senza i materiali necessari per alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, nil, 0x549b28c0, nil, nil, ".m.mm" },
  [97903] = { "Campeggio 101: First Aid", nil, "Quindi ti sei <dedicato/dedicata> al First Aid? Una scelta onorevole... e pragmatica per un {class}.\n\nCredo di conoscere qualcuno che può insegnarti a creare un First Aid Kit per il tuo accampamento. Le ferite sono una realtà nel mondo dell'avventura, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi creare il tuo First Aid Kit. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x6e7c255b, nil, 0x32ff3188, nil, 0x3a282524, ".m.m." },
  [97904] = { "Campeggio 101: Fishing", nil, "Forse non lo penseresti, ma la tua abilità di pescatore può tornare utile all'accampamento.\n\nConosco qualcuno che può insegnarti a creare una Fish Bowl per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e sono sicuro che le tue capacità in combattimento ne risentiranno in meglio.", nil, nil, 0xe0c1c700, nil, 0x1bcf05fd, nil, nil, ".m.mm" },
  [97905] = { "Campeggio 101: Herbalism", nil, "Mi sembra che tu abbia acquisito una certa abilità in erboristeria. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Incense Candle per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e incantatori, e un Incense Candle può dare una spinta che chi usa la magia apprezzerà di sicuro.", nil, nil, 0xd7cde71c, nil, 0xe0048777, nil, nil, ".m.mm" },
  [97906] = { "Campeggio 101: Leatherworking", nil, "Hai imparato la conciatura. Buon per te, {class}. Credo di conoscere qualcuno che può insegnarti a farti una tenda che ti terrà al fresco nei giorni caldi e all'asciutto nei giorni di pioggia.\n\nCon una buona tenda sopra la testa, ti assicurerai tutto il riposo necessario per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, nil, 0x86e620e9, nil, nil, ".m.mm" },
  [97907] = { "Campeggio 101: Mining", nil, "L'estrazione mineraria non sarà il mestiere più affascinante, ma è un lavoro onesto e una buona professione da esplorare.\n\nConosco qualcuno che può insegnarti a creare una Lodestone per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada si radunerà volentieri attorno al tuo fuoco per assorbire quella \"spinta\" in più che può dare alle sue capacità in combattimento.", nil, nil, 0xa8fe12f3, nil, 0x8ef0fff6, nil, nil, ".m.mm" },
  [97908] = { "Campeggio 101: Skinning", nil, "Saper ricavare con abilità pelli e cuoio dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nCredo di conoscere qualcuno che può insegnarti a creare una Camp Chair per il tuo accampamento. A volte è importante semplicemente riposarsi, e puoi usare un po' delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a essere al massimo della forma e a colpire dove conta la prossima volta che ti troverai in una zuffa.", nil, "Ecco fatto: ora puoi creare il tuo Camp Chair. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x14236b38, nil, 0x1755b1ba, nil, 0x98c24a76, ".m.m." },
  [97914] = { "Nuovi orizzonti", "Porta la Thundris' Letter a Baros Alexston, a Stormwind.\n\nThundris ha parlato di una nave ad Auberdine che può portarti lì.", "Auberdine è un luogo umile, {class}. Non sentirai pronunciare il suo nome tra le fronde di Darnassus. I più ricordano solo ciò che il Sundering ci ha tolto: le fiorenti città di Ameth'Aran, Bashal'Aran e... Lathar'Lazal.\n\nEppure Auberdine resta alla loro ombra.\n\nVorrei che il nostro lavoro qui venisse riconosciuto. Una nuova nave ci collega al regno di Stormwind, portando vita e rifornimenti alle nostre coste. Ti supplico di unirti al suo prossimo viaggio e di portare questa lettera a un umano di nome Baros Alexston.\n\nFai conoscere la nostra casa.", "Sento l'odore del mare su di te, amico!\n\n<Baros ride.>\n\nCosa ti porta a Stormwind?", "<Baros apre la lettera e comincia a leggerla, mentre il sorriso gli svanisce.>", 0x47bf47e5, 0xe531658d, 0x0d17a10a, 0xccc0bbea, 0x30ab094d, "....." },
  [97915] = { "Campeggio 101: Alchemy", nil, "Quindi hai scelto di preparare intrugli e pozioni come alchimista. Sono sicuro che ti tornerà utile nei tuoi viaggi.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Mana Well per il tuo accampamento. Costruiscine uno e tutti i guaritori e gli incantatori accorreranno per un sorso rinfrescante.", nil, nil, 0x32f4ba12, nil, 0xf6c52c29, nil, nil, ".m.mm" },
  [97916] = { "Campeggio 101: Blacksmithing", "Parla con Smith Argus a Goldshire per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi sei <diventato/diventata> fabbro. Ottima scelta, se vuoi essere <sicuro/sicura> che le tue lame non perdano mai il filo.\n\nCredo di conoscere qualcuno che può aiutarti insegnandoti a creare una Sharpening Wheel. Portane una al tuo accampamento e tutti i guerrieri e i ladri della zona faranno la fila per affilare le loro armi.", nil, "Ecco fatto, ora puoi creare una Sharpening Wheel tutto tuo. Alla maggior parte della gente non piace che si montino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0x16979ea3, 0xbc0dd4f8, 0x469a706e, nil, 0xe5c38af5, "...m." },
  [97917] = { "Campeggio 101: Enchanting", nil, "Gli incantatori rendono tutto migliore e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. È così importante trovare un po' di svago durante il riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando tornerai sulla vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [97918] = { "Campeggio 101: Engineering", "Parla con Sprite Jumpsprocket a Stormwind per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventare ogni sorta di aggeggi, robot e bombe, per divertimento e per profitto.\n\nConosco qualcuno che può insegnarti a creare un Reagent Bot per il tuo accampamento. Questo utile automa può tenerti ben rifornito, così che tu e i tuoi alleati non restiate mai senza i materiali necessari per alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xba6c8a24, 0x549b28c0, nil, nil, "...mm" },
  [97919] = { "Campeggio 101: First Aid", nil, "Quindi ti sei <dedicato/dedicata> al First Aid? Una scelta onorevole... e pragmatica per un {class}.\n\nCredo di conoscere qualcuno che può insegnarti a creare un First Aid Kit per il tuo accampamento. Le ferite sono una realtà nel mondo dell'avventura, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi creare il tuo First Aid Kit. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x6e7c255b, nil, 0x32ff3188, nil, 0x3a282524, ".m.m." },
  [97920] = { "Campeggio 101: Fishing", "Parla con Lee Brown vicino a Goldshire per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Forse non lo penseresti, ma la tua abilità di pescatore può tornare utile all'accampamento.\n\nConosco qualcuno che può insegnarti a creare una Fish Bowl per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e sono sicuro che le tue capacità in combattimento ne risentiranno in meglio.", nil, "Ecco fatto, ora puoi creare una Fish Bowl tutto tuo. Alla maggior parte della gente non piace che si montino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0xe0c1c700, 0xc4adeb37, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [97921] = { "Campeggio 101: Herbalism", nil, "Mi sembra che tu abbia acquisito una certa abilità in erboristeria. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Incense Candle per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e incantatori, e un Incense Candle può dare una spinta che chi usa la magia apprezzerà di sicuro.", nil, "Ecco fatto: ora puoi creare il tuo Incense Candle. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0xd7cde71c, nil, 0xe0048777, nil, 0x52608ebe, ".m.m." },
  [97922] = { "Campeggio 101: Leatherworking", nil, "Hai imparato la conciatura. Buon per te, {class}. Credo di conoscere qualcuno che può insegnarti a farti una tenda che ti terrà al fresco nei giorni caldi e all'asciutto nei giorni di pioggia.\n\nCon una buona tenda sopra la testa, ti assicurerai tutto il riposo necessario per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, nil, 0x86e620e9, nil, nil, ".m.mm" },
  [97923] = { "Campeggio 101: Mining", "Parla con Gelman Stonehand a Stormwind per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'estrazione mineraria non sarà il mestiere più affascinante, ma è un lavoro onesto e una buona professione da esplorare.\n\nConosco qualcuno che può insegnarti a creare una Lodestone per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada si radunerà volentieri attorno al tuo fuoco per assorbire quella \"spinta\" in più che può dare alle sue capacità in combattimento.", nil, "Ecco fatto, ora puoi creare una Lodestone tutto tuo. Alla maggior parte della gente non piace che si montino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0xa8fe12f3, 0x996abb28, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97924] = { "Campeggio 101: Skinning", nil, "Saper ricavare con abilità pelli e cuoio dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nCredo di conoscere qualcuno che può insegnarti a creare una Camp Chair per il tuo accampamento. A volte è importante semplicemente riposarsi, e puoi usare un po' delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a essere al massimo della forma e a colpire dove conta la prossima volta che ti troverai in una zuffa.", nil, "Ecco fatto: ora puoi creare il tuo Camp Chair. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x14236b38, nil, 0x1755b1ba, nil, 0x98c24a76, ".m.m." },
  [97925] = { "Campeggio 101: Tailoring", "Parla con Eldrin all'Eastvale Logging Camp, nell'Elwynn Forest, per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "La sartoria è un mestiere sorprendentemente potente su cui investire, e sono sicuro che ti servirà bene.\n\nConosco qualcuno che può insegnarti a creare un Faction Banner per il tuo accampamento, se ne hai l'abilità. Ispirazione e morale sono fondamentali per il successo su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0x7350f5be, 0x49663bd1, nil, nil, "...mm" },
  [97926] = { "Arrangiarsi", "Porta l'Alexston's Reply a Thundris Windweaver, ad Auberdine, a Darkshore.", "Vorrei che fosse così facile aiutare, {class}. Davvero.\n\nSe deciderai di passare più tempo nelle nostre terre, scoprirai che molti sono nel bisogno. Le casse di Stormwind non sono più quelle di un tempo, e ciò che resta è distribuito con parsimonia.\n\nDa' questa risposta all'anziano la prossima volta che lo vedi. Non è ciò che spera, ma è tutto ciò che posso offrire per ora.", "Sei <tornato/tornata>. Che notizie porti da Stormwind?", "Brutte notizie davvero. Comunque ti ringrazio per aver fatto il viaggio.\n\nCon né Stormwind né Darnassus disposti ad aiutarci, sembra che il destino di Auberdine spetti a noi soli.", 0xe4477319, 0xeee57b55, 0x5de57436, 0x33442a57, 0x68b57782, "....." },
  [97927] = { "Campeggio 101: Alchemy", nil, "Quindi hai scelto di preparare intrugli e pozioni come alchimista. Sono sicuro che ti tornerà utile nei tuoi viaggi.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Mana Well per il tuo accampamento. Costruiscine uno e tutti i guaritori e gli incantatori accorreranno per un sorso rinfrescante.", nil, nil, 0x32f4ba12, nil, 0xf6c52c29, nil, nil, ".m.mm" },
  [97928] = { "Campeggio 101: Blacksmithing", nil, "Quindi sei <diventato/diventata> fabbro. Ottima scelta, se vuoi essere <sicuro/sicura> che le tue lame non perdano mai il filo.\n\nCredo di conoscere qualcuno che può aiutarti insegnandoti a creare una Sharpening Wheel. Portane una al tuo accampamento e tutti i guerrieri e i ladri della zona faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, nil, 0x469a706e, nil, nil, ".m.mm" },
  [97929] = { "Campeggio 101: Enchanting", nil, "Gli incantatori rendono tutto migliore e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. È così importante trovare un po' di svago durante il riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando tornerai sulla vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [97930] = { "Campeggio 101: Engineering", nil, "Gli ingegneri come te sanno inventare ogni sorta di aggeggi, robot e bombe, per divertimento e per profitto.\n\nConosco qualcuno che può insegnarti a creare un Reagent Bot per il tuo accampamento. Questo utile automa può tenerti ben rifornito, così che tu e i tuoi alleati non restiate mai senza i materiali necessari per alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, nil, 0x549b28c0, nil, nil, ".m.mm" },
  [97931] = { "Campeggio 101: First Aid", nil, "Quindi ti sei <dedicato/dedicata> al First Aid? Una scelta onorevole... e pragmatica per un {class}.\n\nCredo di conoscere qualcuno che può insegnarti a creare un First Aid Kit per il tuo accampamento. Le ferite sono una realtà nel mondo dell'avventura, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi creare il tuo First Aid Kit. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x6e7c255b, nil, 0x32ff3188, nil, 0x3a282524, ".m.m." },
  [97932] = { "Campeggio 101: Fishing", nil, "Forse non lo penseresti, ma la tua abilità di pescatore può tornare utile all'accampamento.\n\nConosco qualcuno che può insegnarti a creare una Fish Bowl per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e sono sicuro che le tue capacità in combattimento ne risentiranno in meglio.", nil, "Ecco fatto, ora puoi creare una Fish Bowl tutto tuo. Alla maggior parte della gente non piace che si montino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0xe0c1c700, nil, 0x1bcf05fd, nil, 0x54727538, ".m.m." },
  [97933] = { "Campeggio 101: Herbalism", nil, "Mi sembra che tu abbia acquisito una certa abilità in erboristeria. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Incense Candle per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e incantatori, e un Incense Candle può dare una spinta che chi usa la magia apprezzerà di sicuro.", nil, nil, 0xd7cde71c, nil, 0xe0048777, nil, nil, ".m.mm" },
  [97934] = { "Campeggio 101: Leatherworking", nil, "Hai imparato la conciatura. Buon per te, {class}. Credo di conoscere qualcuno che può insegnarti a farti una tenda che ti terrà al fresco nei giorni caldi e all'asciutto nei giorni di pioggia.\n\nCon una buona tenda sopra la testa, ti assicurerai tutto il riposo necessario per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, nil, 0x86e620e9, nil, nil, ".m.mm" },
