  [97972] = { "Campeggio 101: Tailoring", nil, "La sartoria è un mestiere sorprendentemente potente su cui investire, e sono sicuro che ti servirà bene.\n\nConosco qualcuno che può insegnarti a creare un Faction Banner per il tuo accampamento, se ne hai l'abilità. Ispirazione e morale sono fondamentali per il successo su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, nil, 0x49663bd1, nil, nil, ".m.mm" },
  [97973] = { "Campeggio 101: Tailoring", nil, "La sartoria è un mestiere sorprendentemente potente su cui investire, e sono sicuro che ti servirà bene.\n\nConosco qualcuno che può insegnarti a creare un Faction Banner per il tuo accampamento, se ne hai l'abilità. Ispirazione e morale sono fondamentali per il successo su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, nil, 0x49663bd1, nil, nil, ".m.mm" },
  [97977] = { "Il richiamo della natura", "Raccogli $N1 Gnarlpine Totems e portali a Tarindrella.", "I furbolg Gnarlpine non si rivolterebbero così facilmente contro i loro antichi alleati. Dobbiamo saperne di più sulla loro situazione.\n\nCerca dei totem nelle loro dimore abbandonate. Se qualcuno è sopravvissuto al caos della loro partenza, le loro incisioni potrebbero dirci di più su ciò che è accaduto qui.\n\nTroverai i loro accampamenti lungo il margine occidentale della valle, anche se i grell e i grellkin potrebbero averli sparpagliati più lontano.", "Non preoccuparti dei totem più grandi che potresti trovare. Non saprei cosa farne se trovassi il modo di prenderli!", "Oh, è persino peggio di quanto pensassi.\n\nQueste incisioni ci dicono che i Gnarlpine cominciarono ad avere incubi in cui venivano spazzati via da una grande ombra. Ben presto quella paura si trasformò in rabbia, e l'ombra nei loro antichi amici elfi. Rendersi conto che la propria mente ti sta sfuggendo...\n\nLa nostra unica speranza è che questo ci aiuti a capire meglio cosa sta accadendo a Teldrassil. Grazie per il tuo aiuto, {name}.", 0x8ddb1b2f, 0x0263ede4, 0x02e09ddc, 0xc1ecd12f, 0x12ba2b7d, "....." },
  [97979] = { "La dea provvede", "Lancia Elune's Light e Shadowmeld.", "Sei <nato/nata> kaldorei, i figli delle stelle, e hai ereditato un diritto di nascita diverso da qualsiasi altro in questo mondo. La grazia di Elune può illuminare i nostri punti di forza, aiutando i nostri colpi ad andare a segno, oppure può aiutarci a nasconderci proprio come la luna può eclissare il sole.\n\nLa nostra lunga veglia dopo la difesa del Mount Hyjal è terminata, e ci siamo uniti a un'Alliance con altri popoli, che incontrerai a tempo debito. Per ora sei al sicuro tra i rami di Teldrassil.\n\nDimostra i doni della madre luna e crogiolati nelle sue benedizioni.", nil, "Hai visto cosa ci dona la nostra dea. Usalo bene, e non ti abbandonerà mai.", 0x1c2fae6f, 0x2d344d16, 0x2061ad94, nil, 0xc6da7ff1, "...m." },
})
